import { useQuery } from '@tanstack/react-query'
import { api } from '../../api'
import { buildText } from '../../lib/build'
import { CREDITS } from '../../lib/credits'
import { Ext, Section } from './parts'

/** Settings › About: the licence, the third-party notices the server
 * serves (THIRD_PARTY_NOTICES.txt, generated by contrib/notices/), and where
 * the game data comes from, with the attribution each source's terms ask
 * for (docs/THIRD_PARTY.md). */
export function AboutSection() {
  const health = useQuery({ queryKey: ['health'], queryFn: api.health, retry: false })
  return (
    <Section id="about" title="About" desc="UpNext is open source under MIT OR Apache-2.0.">
      {health.data && <p className="mt-4 mb-0 text-[14.5px] text-muted">{buildText(health.data)}</p>}
      <p className="mt-4 mb-0 max-w-[70ch] text-[14.5px] text-muted">
        UpNext's website is <Ext href="https://upnext.games">upnext.games</Ext>. Source, issues and the licence are on{' '}
        <Ext href="https://github.com/zytocc/upnext">GitHub</Ext>. UpNext is built with open-source
        libraries, fonts and icons, each under its own licence: the <Ext href="/third-party-notices.txt">third-party notices</Ext> list
        them with their licence texts.
      </p>
      <p className="mt-4 mb-0 max-w-[70ch] text-[14.5px] text-muted">
        Game data comes from these services, under their own terms. UpNext isn't affiliated with any of them.
      </p>
      <ul aria-label="Data sources" className="m-0 mt-2 grid list-none grid-cols-1 p-0 lg:grid-cols-2 lg:gap-x-14">
        {CREDITS.map((c) => (
          <li key={c.name} className="min-w-0 border-b border-line py-3.5">
            <div className="text-[15.5px] font-bold">
              <Ext href={c.url}>{c.name}</Ext>
            </div>
            <div className="mt-0.5 text-[13.5px] text-dim">{c.what}</div>
            {(c.note || c.terms) && (
              <div className="mt-0.5 text-[13.5px] text-dim">
                {c.note}
                {c.note && c.terms && ' '}
                {c.terms && <Ext href={c.terms.url}>{c.terms.label}</Ext>}
              </div>
            )}
          </li>
        ))}
      </ul>
    </Section>
  )
}
